```

### 3. Start / pause / resume / restart

```ts
export function startVariation(variation: Variation) {
  if (screen !== "menu") return;
  screen = "game";
  currentVariation = variation;
  savedActions = loadSavedGame()?.actions ?? [];
  drawGame();
}

export function resumeSavedGame() {
  if (screen !== "menu") return;
  const saved = loadSavedGame();
  if (!saved) return;
  screen = "game";
 currentVariation = variations.find(v => v.id === saved.variationId)!;
  savedActions = saved.actions;
  runSeed = saved.seed;
  drawGame();
}

export function restartGame() {
  clearSavedGame();
  startVariation(currentVariation!);
}

export function leaveToMenu() {
  clearSaved Game(); // keep save
  screen = "menu";
  drawMenu();
}
```

### 4. Pause / resume

```ts
export function togglePause() {
  if (screen !== "game") return;
  screen = screen === "game" ? "paused" : "game";
  drawGame ();
}
```

