`findGame` is already imported; we’ll use it to pick a game and call `startGame`.

```ts
// menu.ts – add these helpers
function startGame(selected: GameEntry, variationId: string, options?: { saved?: SavedGame; seed?: number }): void {
 stopTicker();
  stopWorkerOrchestrator();
  restaurantArenaScene?.destroy();
  restaurantArenaScene = undefined;
  game = undefined;
  gameEnded = false;
  runSeed = options?.seed ?? freshSeed();
  runVariationId = variationId;
  savedGame = options?.saved ?? null;

 // restore or fresh start
  if (options?.saved) {
    restoreGame(options.saved);
  } else {
    game = new Restaurant(selected, variationId, runSeed);
  }

  screen = "game";
  drawGame();
  attachWorkerOrchestrator(); // now safe
  persistActiveGame // empty actions on new run
  captureOverlayEvent("game.started", { gameId: game.gameId, variationId });
}

function resumeSavedGame(): void {
  if (!savedGame) return;
  const selected = MENU_GAMES.find(g => g.id === savedGame.gameId);
  if (!selected || !isPlayable(selected)) return;
  startGame(selected, savedGame.variationId, { saved: savedGame });
}
```

Menu button now:
```ts
const startBtn = document.querySelector("#start-game") as HTMLButtonElement;
startBtn?.addEventListener("click", () => {
  const selected = findGame("restaurant");
  if (selected) startGame(selected, selected.variations[0]!.id);
});
```

Next, the window chrome.  
We need `minimize`, `resize`, `How-to-Play`, and sign-out to work.

```ts
// chrome.ts – new file or extend overlay.ts
export function minimizeWindow(): void {
  if (screen === "game") {
    hidePauseDialog();
    hideHowToPlay();
    if (game && !gameEnded) endGame("user_quit");
    stopTicker();
    stopWorkerOrchestrator();
    restaurantArenaScene = undefined;
    game = undefined;
    screen = "menu";
    drawMenu();
  }
  window.api.setFrame("pill");
}

export function restoreWindow(): void {
  window.api.setFrame("compact");
  if (screen === "menu" && savedGame) resumeSavedGame();
  else if ( screen === "menu") drawMenu();
}

export function toggleResize(): void {
  if (screen === "game") {
    hidePauseDialog();
    hideHowToPlay();
    if (game && !gameEnded) endGame("user_quit");
    stopTicker();
    stopWorkerOrchestrator();
    restaurantArenaScene?.destroy();
    restaurantArenaScene = undefined;
    game = undefined;
    screen = "menu";
    drawMenu();
  }
  window.api.toggleFrame();
}

export function showHowToPlay(): void {
  hidePauseDialog();
  const card = document.querySelector(".how-to-play-card");
 card?.classList.toggle("hidden");
}

export function signOut(): void {
  const confirm = document.querySelector("#sign-out-confirm");
  confirm?.classList.toggle("hidden");
}
```

