```ts
document.addEventListener("click", (e) => {
  const t = e.target as HTMLElement;
  if (t.id === "minimize-pill") minimizeWindow();
  if (t.id === "resize-toggle") toggleResize();
  if (t.id === "how-to-play-btn") showHowToPlay();
