```ts
function showGameOver(): void {
  const prompt = document.querySelector<HTMLElement>("#return-prompt");
  if (!prompt) return;
  paused = false;
  const title = prompt.querySelector("#return-title");
  const won = game?.hasWon() ?? false;
  title.textContent = won ? "Shift complete" : "Shift over";
  prompt.dataset.tone = won ? "win" : "loss";
  prompt.hidden = false;

  const card = prompt.query .querySelector(".return-card");
  if (card) {
    card.classList.add("how-to-play-card");
    let extra = card.querySelector(".game-over-extra");
    if (!extra) {
      extra = document.createElement("div");
      extra.className = "game-over-extra";
      card.query .querySelector(".return-actions")?.before(extra);
    }
    extra.innerHTML = `${getArenaDebriefHtml()}${getArenaEvidenceHtml()}${sessionReceiptHtml()}${getArenaTimelineHtml()}
      <div class="export-trace-group">
        <button type="button" data-action="export-trace"> Export Trace</button>
        <button type="button" data-action="export-trace-jsonl">JSONL</button>
      </div>`;
  }

  const continueBtn = document.querySelector("#continue-game");
  const returnCode = document.querySelector("#return-code");
  continueBtn.textContent = "↻ Restart";
  returnCode.innerHTML = `<kbd>M</kbd> Menu`;
}

function resetReturnPrompt(): void {
  const prompt = document.querySelector<HTMLElement>("#return-prompt");
  if (!prompt) return;
  prompt.hidden = true;
  delete prompt.dataset.tone;
  const title = prompt.query .querySelector("#return-title");
