export function loadSavedGame(storage: Storage = localStorage): SavedGame | null {
  try {
    const raw = storage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const saved: unknown = JSON.parse(raw);
    return validSavedGame(saved) ? saved : null;
  } catch {
    return null;
  }
}

/** Persist the in-progress run. Never throws — gameplay must not stall on quota. */
export function saveGame(saved: SavedGame, storage: Storage = localStorage): void {
  if (!validSavedGame(saved)) return;
  try {
    storage.setItem(STORAGE_KEY, JSON.stringify(saved));
  } catch {
    // Persistence must never interrupt gameplay.
  }
}

/**
 * Drop the active-game record. Restart uses this so the next run cannot
 * inherit the previous seed or action log.
 */
export function clearSavedGame(storage: Storage = localStorage): void {
  try {
    storage.removeItem(STORAGE_KEY);
  } catch {
    // A leftover record only means resume may offer a stale game.
  }
}

/** Unsigned 32-bit seed, never equal to `avoid` (restart must not replay). */
export function newRunSeed(avoid?: number): number {
  const random = (): number => {
    if (typeof crypto !== "undefined" && typeof crypto.getRandomValues === "function") {
      return crypto.getRandomValues(new Uint32Array(1))[0]!;
    }
    return (Math.random() * 0x1_0000_0000) >>> 0;
  };
  for (let attempt = 0; attempt < 8; attempt++) {
    const seed = random();
    if (seed !== avoid) return seed;
  }
  return ((avoid ?? 0) + 1) >>> 0;
}

