import { COMPACT_SIZE, EXPANDED_SIZE, MIN_SIZE, PILL_SIZE } from "./tauri-bridge.js";

/** Host lifecycle events the native shell (and tests) dispatch onto `window`. */
export const HOST_EVENTS = {
  pause: "gamepigeon:pause",
  resume: "gamepigeon:resume",
  reset: "gamepigeon:reset",
  launch: "gamepigeon:launch",
} as const;

export type OverlayFrame = "compact" | "expanded" | "pill";

export function sizeForFrame(frame: OverlayFrame): { width: number; height: number } {
  if (frame === "expanded") return EXPANDED_SIZE;
  if (frame === "pill") return PILL_SIZE;
  return COMPACT_SIZE;
}

export function minSizeForFrame(frame: OverlayFrame): { width: number; height: number } {
  return frame === "pill" ? PILL_SIZE : MIN_SIZE;
}

/** Hide (`Esc` / `q` / the hide button) always collapses to the handheld pill. */
export function frameAfterHide(): "pill" {
  return "pill";
}

/**
 * Clicking the pill restores the compact frame — never the previous expanded
 * size, and never smaller than `MIN_SIZE`.
 */
export function frameAfterRestore(): "compact" {
  return "compact";
}

export function toggleExpandedFrame(expanded: boolean): "compact" | "expanded" {
  return expanded ? "compact" : "expanded";
}

