import { describe, expect, test } from "bun:test";
import { COMPACT_SIZE, EXPANDED_SIZE, MIN_SIZE, PILL_SIZE, PREVIEW_RESIZE_MESSAGE } from "./tauri-bridge.js";

describe("overlay frame sizes", () => {
  test("exports the production overlay frame sizes from the README", () => {
    expect(COMPACT_SIZE).toEqual({ width: 600, height: 850 });
    expect(EXPANDED_SIZE).toEqual({ width: 830, height: 900 });
    expect(PILL_SIZE).toEqual({ width: 144, height: 48 });
    expect(MIN_SIZE).toEqual({ width: 500, height: 700 });
  });

  test("names the preview resize message the browser frame listens for", () => {
    expect(PREVIEW_RESIZE_MESSAGE).toBe("gamepigeon:preview-resize");
  });
});

import { describe, expect, test } from "bun:test";
import { COMPACT_SIZE, EXPANDED_SIZE, MIN_SIZE, PILL_SIZE } from "./tauri-bridge.js";
import {
  HOST_EVENTS,
  frameAfterHide,
  frameAfterRestore,
  minSizeForFrame,
  sizeForFrame,
  toggleExpandedFrame,
} from "./pause-state.js";

describe("overlay window chrome", () => {
  test("hide collapses to the pill, restore returns to compact above the floor", () => {
    expect(frameAfterHide()).toBe("pill");
    expect(sizeForFrame(frameAfterHide())).toEqual(PILL_SIZE);
    expect(minSizeForFrame("pill")).toEqual(PILL_SIZE);

    expect(frameAfterRestore()).toBe("compact");
    expect(sizeForFrame(frameAfterRestore())).toEqual(COMPACT_SIZE);
    expect(minSizeForFrame("compact")).toEqual(MIN_SIZE);
    expect(COMPACT_SIZE.width).toBeGreaterThanOrEqual(MIN_SIZE.width);
    expect(COMPACT_SIZE.height).toBeGreaterThanOrEqual(MIN_SIZE.height);
  });

  test("the expand control toggles compact and expanded frames", () => {
    expect(sizeForFrame(toggleExpandedFrame(false))).toEqual(EXPANDED_SIZE);
    expect(sizeForFrame(toggleExpandedFrame(true))).toEqual(COMPACT_SIZE);
  });

  test("host lifecycle event names match the native shell", () => {
    expect(HOST_EVENTS.pause).toBe("gamepigeon:pause");
    expect(HOST_EVENTS.resume).toBe("gamepigeon:resume");
    expect(HOST_EVENTS.reset).toBe("gamepigeon:reset");
    expect(HOST_EVENTS.launch).toBe("gamepigeon:launch");
  });
});

import { describe, expect, test } from "bun:test";
import { MENU_GAMES } from "../src/games/registry.js";
import {
  clearSavedGame,
  loadSavedGame,
  newRunSeed,
  restoreGame,
  saveGame,
  type SavedGame,
} from "./persistence.js";

function memoryStorage(initial: Record<string, string> = {}): Storage {
  const map = new Map(Object.entries(initial));
  return {
    getItem: (key) => map.get(key) ?? null,
    setItem: (key, value) => { map.set(key, value); },
    removeItem: (key) => { map.delete(key); },
    clear: () => map.clear(),
    key: (index) => [...map.keys()][index] ?? null,
    get length() { return map.size; },
  } as Storage;
}

const restaurant = MENU_GAMES.find((entry) => entry.id === "restaurant-arena")!;

function sampleSave(overrides: Partial<SavedGame> = {}): SavedGame {
  return {
    schemaVersion: 1,
    ownerId: "usr_test",
    gameId: restaurant.id,
    gameVersion: restaurant.version,
    variationId: "dinner-rush",
    seed: 42,
    actions: ["sim_toggle", "tick"],
    ...overrides,
  };
}

describe("active-game persistence", () => {
  test("round-trips a valid SavedGame through storage", () => {
    const storage = memoryStorage();
    const saved = sampleSave();
    saveGame(saved, storage);
    expect(loadSavedGame(storage)).toEqual(saved);
  });

  test("rejects malformed records instead of crashing resume", () => {
    const storage = memoryStorage({
      "gamepigeon.arcade.active-game.v1": "{not json",
    });
    expect(loadSavedGame(storage)).toBeNull();
    saveGame({ ...sampleSave(), seed: 1.5 }, storage);
    expect(loadSavedGame(storage)).toBeNull();
  });

  test("rebuilds the same run from seed plus the action log", () => {
    const saved = sampleSave();
    const restored = restoreGame(restaurant, saved);
    expect(restored).not.toBeNull();
    expect(restored!.actions).toEqual(saved.actions);

    const fresh = restaurant.create!(saved.variationId);
    fresh.reset(saved.seed);
    for (const action of saved.actions) fresh.step(action);
    expect(restored!.game.state()).toEqual(fresh.state());
  });

  test("ending a shift keeps the record; restart throws it away", () => {
    const storage = memoryStorage();
    const saved = sampleSave();
    saveGame(saved, storage);
    // Menu / host reset: leave the seed and action log untouched.
    expect(loadSavedGame(storage)?.seed).toBe(42);
    expect(loadSavedGame(storage)?.actions).toEqual(["sim_toggle", "tick"]);

    clearSavedGame(storage);
    const restart = sampleSave({ seed: newRunSeed(saved.seed), actions: [] });
    saveGame(restart, storage);
    const next = loadSavedGame(storage)!;
    expect(next.actions).toEqual([]);
    expect(next.seed).not.toBe(saved.seed);
  });

  test("newRunSeed never reuses the run it replaces", () => {
    for (let i = 0; i < 20; i++) {
      expect(newRunSeed(123)).not.toBe(123);
    }
  });
});

