function currentFrame(): OverlayFrame {
  if (minimized) return "pill";
  return expanded ? "expanded" : "compact";
}

function updateResizeButton(): void {
  const button = document.querySelector<HTMLButtonElement>("#resize");
  if (!button) return;
  button.textContent = expanded ? "↙" : "↗";
  button.setAttribute("aria-label", expanded ? "Compact overlay" : "Expand overlay");
  button.title = expanded ? "Compact the overlay" : "Expand or compact";
}

async function applyOverlayFrame(frame: OverlayFrame): Promise<void> {
  const size = sizeForFrame(frame);
  const min = minSizeForFrame(frame);
  await windowHandle.setMinSize(overlayLogicalSize(min.width, min.height));
  await windowHandle.setSize(overlayLogicalSize(size.width, size.height));
}

async function toggleExpanded(): Promise<void> {
  if (minimized) return;
  expanded = toggleExpandedFrame(expanded) === "expanded";
  await applyOverlayFrame(currentFrame());
  updateResizeButton();
}

async function hideToPill(): Promise<void> {
  minimized = true;
  document.body.dataset.mode = "pill";
  workerOrchestrator?.pause();
  stopTicker();
  await applyOverlayFrame(frameAfterHide());
}

async function restoreFromPill(): Promise<void> {
  if (!minimized) return;
  minimized = false;
  delete document.body.dataset.mode;
  expanded = false;
  await applyOverlayFrame(frameAfterRestore());
  updateResizeButton();
  if (screen === "game" && !paused && !gameEnded) drawGame();
}

function dialogElement(id: string): HTMLElement | null {
  return document.querySelector<HTMLElement>(`#${id}`);
}

function isDialogOpen(id: string): boolean {
  const element = dialogElement(id);
  return !!element && !element.hidden;
}

function showHowToPlay(): void {
  const dialog = dialogElement("how-to-play");
  if (dialog) dialog.hidden = false;
}

function hideHowToPlay(): void {
  const dialog = dialogElement("how-to-play");
  if (dialog) dialog.hidden = true;
}

function showSignOutPrompt(): void {
  const dialog = dialogElement("signout-prompt");
  if (dialog) dialog.hidden = false;
}

function hideSignOutPrompt(): void {
  const dialog = dialogElement("signout-prompt");
  if (dialog) dialog.hidden = true;
}

function resetReturnPrompt(): void {
  const prompt = dialogElement("return-prompt");
  if (!prompt) return;
  prompt.hidden = true;
  delete prompt.dataset.tone;
  const title = prompt.querySelector("#return-title");
  if (title) title.textContent = "Paused";
  prompt.querySelector(".game-over-extra")?.remove();
  prompt.querySelector(".return-card")?.classList.remove("how-to-play-card");
  const continueBtn = document.querySelector("#continue-game");
  const howFromPause = document.querySelector<HTMLButtonElement>("#how-to-play-from-pause");
  const returnCode = document.querySelector("#return-code");
  if (continueBtn) continueBtn.textContent = "Continue playing";
  if (returnCode) returnCode.innerHTML = "<kbd>Esc</kbd> Back to coding";
  if (howFromPause) howFromPause.hidden = false;
}

function showPauseDialog(): void {
  if (gameEnded) return;
  const prompt = dialogElement("return-prompt");
  if (!prompt) return;
  resetReturnPrompt();
  prompt.hidden = false;
}

function continuePlaying(): void {
  paused = false;
  resetReturnPrompt();
  hideHowToPlay();
  if (screen === "game" && !gameEnded) drawGame();
}

async function pauseForAgent(): Promise<void> {
  if (screen !== "game" || gameEnded) return;
  if (minimized) await restoreFromPill();
  paused = true;
  workerOrchestrator?.pause();
  stopTicker();
  showPauseDialog();
}

async function resumeFromHost(): Promise<void> {
  if (minimized) await restoreFromPill();
  if (paused && !gameEnded) continuePlaying();
}

function stopTicker(): void {
  if (tickTimer !== undefined) {
    window.clearTimeout(tickTimer);
    tickTimer = undefined;
  }
}

function enterScheduler(): void {
  stopTicker();
  if (!game || game.isOver() || paused || minimized || gameEnded) return;
  const ms = game.tickMs?.() ?? 0;
  if (workerOrchestrator) {
    if (ms > 0) workerOrchestrator.start();
    else workerOrchestrator.pause();
    return;
  }
  if (ms <= 0) return;
  tickTimer = window.setTimeout(() => {
    tickTimer = undefined;
    performAction("tick");
  }, ms);
}

function persistActiveGame(): void {
  if (replaying || !entry || !game) return;
  const record: SavedGame = {
    schemaVersion: 1,
    ownerId: signedInUser()?.id ?? "",
    gameId: entry.id,
    gameVersion: entry.version,
    variationId: runVariationId,
    seed: runSeed,
    actions: runActions,
  };
  savedGame = record;
  saveGame(record);
}

function variationIdAt(selected: GameEntry, index: number): string {
  return selected.variations[index]?.id ?? selected.variations[0]!.id;
}

function startSelectedVariation(): void {
  if (!entry) return;
  startGame(entry, variationIdAt(entry, variationCursor));
}

function resumeSavedGame(): void {
  if (!savedGame) return;
  const selected = MENU_GAMES.find((item) => item.id === savedGame!.gameId);
  if (!selected || !isPlayable(selected)) return;
  startGame(selected, savedGame.variationId, { saved: savedGame });
}

function launchById(gameId: string, variationId?: string): boolean {
  const selected = findGame(gameId);
  if (!selected || !isPlayable(selected)) return false;
  const resolved = variationId && selected.variations.some((item) => item.id === variationId)
    ? variationId
    : selected.variations[0]!.id;
  cursor = MENU_GAMES.findIndex((item) => item.id === selected.id);
  entry = selected;
  variationCursor = Math.max(0, selected.variations.findIndex((item) => item.id === resolved));
  startGame(selected, resolved);
  return true;
}

function startGame(
  selected: GameEntry,
  variationId: string,
  options: { saved?: SavedGame; seed?: number } = {},
): void {
  if (!selected.create) return;
  hideHowToPlay();
  resetReturnPrompt();
  stopTicker();
  stopWorkerOrchestrator();
  restaurantArenaScene?.destroy();
  restaurantArenaScene = undefined;
  if (game && !gameEnded && activeTrace) {
    submitTrace(activeTrace, "user_quit");
    activeTrace = undefined;
  }

  entry = selected;
  runVariationId = variationId;
  variationCursor = Math.max(0, selected.variations.findIndex((item) => item.id === variationId));
  replaying = false;
  gameEnded = false;
  paused = false;
  actionsTaken = 0;
  gameStartedAt = Date.now();

  let restoredActions: string[] | undefined;
  if (options.saved) {
    const restored = restoreGame(selected, options.saved);
    if (restored) {
      game = restored.game;
      runSeed = options.saved.seed;
      runActions = [...restored.actions];
      restoredActions = restored.actions;
    }
  }
  if (!game || restoredActions === undefined) {
    runSeed = options.seed ?? newRunSeed();
    runActions = [];
    game = selected.create(variationId);
    game.reset(runSeed);
  }

  screen = "game";
  activeTrace = createOverlayTrace(selected, variationId, runSeed, gameStartedAt);
  gameSessionId = activeTrace.gameId;
  sessionReceiptId = activeTrace.gameId;
  persistTrace(activeTrace);
  persistActiveGame();
  captureOverlayEvent("game.started", {
    game_type: selected.id,
    variation_id: variationId,
  }, gameSessionId);
  renderGameScreen();
  if (game.name !== "restaurant-arena") attachWorkerOrchestrator(game);
  enterScheduler();
}

function restartGame(): void {
  if (!entry) return;
  const selected = entry;
  const variationId = runVariationId || variationIdAt(selected, variationCursor);
  const previousSeed = runSeed;
  endGame("restart");
  startGame(selected, variationId, { seed: newRunSeed(previousSeed) });
}

function leaveToMenu(): void {
  hideHowToPlay();
  resetReturnPrompt();
  paused = false;
  if (game && !gameEnded) endGame("user_quit");
  stopTicker();
  stopWorkerOrchestrator();
  restaurantArenaScene?.destroy();
  restaurantArenaScene = undefined;
  game = undefined;
  screen = "menu";
  drawMenu();
}

function endGame(reason: EpisodeEndReason): void {
  if (gameEnded && reason !== "restart") return;
  gameEnded = true;
  stopTicker();
  stopWorkerOrchestrator();
  cancelTraceFlush();
  const completed = reason === "game_over" || reason === "won" || reason === "lost";
  const score = game?.score() ?? 0;
  const success = game?.hasWon() ?? false;
  if (entry && game) {
    lastReplay = {
      entry,
      variationId: runVariationId,
      seed: runSeed,
      actions: [...runActions],
    };
  }
  if (activeTrace) {
    submitTrace(activeTrace, reason, completed ? score : undefined);
    activeTrace = undefined;
  }
  if (entry) {
    captureOverlayEvent("game.ended", {
      game_type: entry.id,
