}

function restartGame(): void {
  if (!entry) return;
  const selected = entry;
  const variationId = runVariationId || variationIdAt(selected, variationCursor);
  const previousSeed = runSeed;
  endGame("restart");
  startGame(selected, variationId, { seed: newRunSeed(previousSeed) });
}

function leaveToMenu(): void {
  hideHowToPlay();
  resetReturnPrompt();
  paused = false;
  if (game && !gameEnded) endGame("user_quit");
  stopTicker();
  stopWorkerOrchestrator();
  restaurantArenaScene?.destroy();
  restaurantArenaScene = undefined;
  game = undefined;
  screen = "menu";
  drawMenu();
}

function endGame(reason: EpisodeEndReason): void {
  if (gameEnded && reason !== "restart") return;
  gameEnded = true;
  stopTicker();
  stopWorkerOrchestrator();
  cancelTraceFlush();
  const completed = reason === "game_over" || reason === "won" || reason === "lost";
  const score = game?.score() ?? 0;
  const success = game?.hasWon() ?? false;
  if (entry && game) {
    lastReplay = {
      entry,
      variationId: runVariationId,
      seed: runSeed,
      actions: [...runActions],
    };
  }
  if (activeTrace) {
    submitTrace(activeTrace, reason, completed ? score : undefined);
    activeTrace = undefined;
  }
  if (entry) {
    captureOverlayEvent("game.ended", {
      game_type: entry.id,
      variation_id: runVariationId,
      outcome: completed ? "completed" : "abandoned",
      score,
      success,
      duration_ms: Math.max(0, Date.now() - gameStartedAt),
      actions_taken: actionsTaken,
    }, gameSessionId);
  }
  if (completed) {
    clearSavedGame();
    savedGame = undefined;
    if (gameSessionId && entry) {
      void invoke("append_local_score", {
        score: {
          game_id: gameSessionId,
          game_type: entry.id,
          variation_id: runVariationId,
          score,
          success,
          completed_at: new Date().toISOString(),
          duration_ms: Math.max(0, Date.now() - gameStartedAt),
          platform: "overlay",
        },
      }).then(() => refreshLocalScores()).catch(() => undefined);
    }
    showGameOver();
  } else if (reason === "restart") {
    clearSavedGame();
    savedGame = undefined;
  }
}

function showGameOver(): void {
  const prompt = dialogElement("return-prompt");
  if (!prompt || !game) return;
  paused = false;
  const title = prompt.querySelector("#return-title");
  const won = game.hasWon();
  if (title) title.textContent = won ? "Shift complete" : "Shift over";
  prompt.dataset.tone = won ? "win" : "loss";
  prompt.hidden = false;
  const card = prompt.querySelector(".return-card");
  if (card) {
    card.classList.add("how-to-play-card");
    card.querySelector(".game-over-extra")?.remove();
    const extra = document.createElement("div");
    extra.className = "game-over-extra";
    extra.innerHTML = `${getArenaDebriefHtml()}${getArenaEvidenceHtml()}${sessionReceiptHtml()}${getArenaTimelineHtml()}
      <div class="export-trace-group">
        <button type="button" class="export-trace-btn" data-action="export-trace">Export Trace</button>
        <button type="button" class="export-trace-btn-alt" data-action="export-trace-jsonl">JSONL</button>
      </div>`;
    card.querySelector(".return-actions")?.before(extra);
  }
  const continueBtn = document.querySelector("#continue-game");
  const howFromPause = document.querySelector<HTMLButtonElement>("#how-to-play-from-pause");
  const returnCode = document.querySelector("#return-code");
  if (continueBtn) continueBtn.textContent = "↻ Restart";
  if (returnCode) returnCode.innerHTML = "<kbd>M</kbd> Menu";
  if (howFromPause) howFromPause.hidden = true;
}

async function confirmSignOut(): Promise<void> {
  if (screen === "game") leaveToMenu();
  try {
    await signOut();
  } catch {
    hideSignOutPrompt();
    return;
  }
  hideSignOutPrompt();
  drawGate();
}

function handleChromeClick(target: HTMLElement): boolean {
  if (target.id === "resize") {
    void toggleExpanded();
    return true;
  }
  if (target.id === "hide" || target.id === "return-code") {
    if (target.id === "return-code" && gameEnded) leaveToMenu();
    else void hideToPill();
    return true;
  }
  if (target.id === "shutdown") {
    void invoke("shutdown");
    return true;
  }
  if (target.id === "continue-game") {
    if (gameEnded) restartGame();
    else continuePlaying();
    return true;
  }
  if (target.id === "return-menu") {
    leaveToMenu();
    return true;
  }
  if (target.id === "how-to-play-from-pause" || target.hasAttribute("data-open-how-to-play")) {
    showHowToPlay();
    return true;
  }
  if (target.id === "how-to-play-close") {
    hideHowToPlay();
    return true;
  }
  if (target.id === "signout-confirm") {
    void confirmSignOut();
    return true;
  }
  if (target.id === "signout-cancel") {
    hideSignOutPrompt();
    return true;
  }
  if (target.dataset.action === "export-trace") {
    exportCurrentTrace("json");
    return true;
  }
  if (target.dataset.action === "export-trace-jsonl") {
    exportCurrentTrace("jsonl");
    return true;
  }
  return false;
}


