  pillDragged = false;
  const startX = event.clientX;
  const startY = event.clientY;
  const onMove = (move: MouseEvent) => {
    if (Math.abs(move.clientX - startX) > 4 || Math.abs(move.clientY - startY) > 4) pillDragged = true;
  };
