import { Window } from "happy-dom";
import { readFileSync } from "node:fs";

const html = readFileSync("/app/overlay/dist/index.html", "utf8");
const happy = new Window({ url: "http://127.0.0.1/" });
const doc = happy.document;
doc.write(html);

const g = globalThis as typeof globalThis & { window: typeof happy; document: typeof doc };
g.window = happy as unknown as typeof g.window;
g.document = doc as unknown as Document;
(g as { HTMLElement: unknown }).HTMLElement = happy.HTMLElement;
(g as { CustomEvent: unknown }).CustomEvent = happy.CustomEvent;
(g as { localStorage: Storage }).localStorage = happy.localStorage as unknown as Storage;
g.requestAnimationFrame = (cb: FrameRequestCallback) => happy.setTimeout(() => cb(0), 0) as unknown as number;
g.cancelAnimationFrame = (id: number) => happy.clearTimeout(id);

await import("/app/overlay/app.ts");
await Bun.sleep(50);

const screen = doc.querySelector("#screen") as HTMLElement;
console.log("screen after boot:", screen?.dataset.screen, screen?.innerHTML.slice(0, 180));

const card = screen.querySelector("[data-game-index]") as HTMLButtonElement | null;
console.log("game card", card?.textContent?.slice(0, 80));
card?.click();
await Bun.sleep(20);
console.log("after game click:", screen.dataset.screen);

const variation = screen.querySelector("[data-variation-index]") as HTMLButtonElement | null;
console.log("variation card", variation?.textContent?.slice(0, 80));
variation?.click();
await Bun.sleep(50);
console.log("after variation click:", screen.dataset.screen, screen.dataset.game);
console.log("has phaser mount", !!screen.querySelector("[data-phaser-mount]"));

const how = doc.querySelector("[data-open-how-to-play]") as HTMLButtonElement | null;
console.log("how to play on screen", !!how);

(doc.querySelector("#resize") as HTMLButtonElement).click();
await Bun.sleep(10);
console.log("resize label", (doc.querySelector("#resize") as HTMLButtonElement).getAttribute("aria-label"));

(doc.querySelector("#hide") as HTMLButtonElement).click();
await Bun.sleep(10);
console.log("body mode", doc.body.getAttribute("data-mode"));

